'use strict';
/* public/js/86-voice.js -- WebRTC proximity voice chat and positional audio. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- proximity voice chat ---------- */
/* ============================================================
   PROXIMITY VOICE CHAT
   WebRTC peer-to-peer audio mesh, signaled over the existing game WebSocket ('rtc' messages, relayed
   server-side to one target). Positional audio: each remote voice runs through a WebAudio PannerNode
   whose position we update from that player's rendered model position every frame, with the WebAudio
   listener following the camera. Only connect to campers within VOICE_CONNECT m; drop past VOICE_DROP m
   (hysteresis) so the mesh doesn't try to hold N^2 connections on a full camp -- someone that far away
   is inaudible anyway. Voice is opt-in: mic access is only requested when the player turns it on, and a
   peer only answers another's offer while its own voice is on (see handleRtc).
   ============================================================ */
let ICE_SERVERS=[{urls:'stun:stun.l.google.com:19302'}]; // replaced by the server's hello.iceServers (adds TURN if configured there)
const VOICE_CONNECT=60, VOICE_DROP=80; // meters: open a connection / tear one down (gap avoids flapping at the edge)
const VOICE_REF_DIST=4, VOICE_MAX_DIST=36; // panner falloff, tuned close to the text CHAT_RANGE (30m) on the server
const VOICE_STALE_MS=6000;
/* walkie-talkies (86-walkie.js): two campers who both own one keep a voice link at any distance, and past plain
   earshot the voice comes through a radio filter instead of from where they stand */
const RADIO_NEAR=18,RADIO_FAR=30,RADIO_VOL=0.6;   // RADIO_VOL: about as loud as someone a few metres away (F2 > Audio > Walkie-talkie scales it)   // m: the radio fades in between these (positional voice fades out by VOICE_MAX_DIST)
const RADIO_CURVE=(()=>{const c=new Float32Array(256);for(let i=0;i<256;i++){const x=i/127.5-1;c[i]=Math.tanh(x*1.6)/1.6}return c})();   // unity gain for quiet speech, loud peaks rounded off like a little speaker
function radioPair(R){return!!(S.up&&S.up.walkie&&R&&(R.f&4096))}
const VOICE_STALE_MS_=VOICE_STALE_MS; // an offer nobody answered (the other side's voice is off): drop it and retry later
const SPEAK_LVL=0.045; // RMS level above which we consider someone "speaking" for the glow indicator
const VOX={enabled:false,mode:'ptt',muted:false,localStream:null,peers:new Map(),selfSrc:null,selfAnalyser:null,selfBuf:null};
let voiceMaster=null; // a sub-bus under the game's master gain, so pressing M mutes voice along with everything else
function ensureVoiceBus(){if(voiceMaster)return;initAudio();voiceMaster=AC.createGain();voiceMaster.gain.value=(VOX.muted?0:1)*SETTINGS.volVoice;voiceMaster.connect(master)}
function sendRtc(to,d){wsSend({t:'rtc',to,d})}
function updateVoiceHud(){
  const b=$('#voiceBtn');b.textContent=VOX.enabled?'Voice on':'Voice off';b.setAttribute('aria-pressed',VOX.enabled?'true':'false');
  $('#voiceModeBtn').hidden=!VOX.enabled;$('#voiceModeBtn').textContent=VOX.mode==='ptt'?'Push-to-talk (hold P)':'Open mic (always on)';
  $('#voiceMuteBtn').hidden=!VOX.enabled;$('#voiceMuteBtn').textContent=VOX.muted?'Unmute voices':'Mute voices';
}
function setMicTransmitting(on){VOX.tx=on;if(VOX.localStream)for(const t of VOX.localStream.getAudioTracks())t.enabled=on}
function setupSelfAnalyser(){
  try{ensureVoiceBus();VOX.selfSrc=AC.createMediaStreamSource(VOX.localStream);VOX.selfAnalyser=AC.createAnalyser();VOX.selfAnalyser.fftSize=512;
    VOX.selfSrc.connect(VOX.selfAnalyser);VOX.selfBuf=new Uint8Array(VOX.selfAnalyser.frequencyBinCount); // analysis tap only -- never connected onward, or you'd hear yourself
  }catch(e){}
}
async function setVoiceEnabled(on){
  if(on===VOX.enabled)return;
  if(on){
    ensureVoiceBus();
    try{VOX.localStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}})}
    catch(e){toast('Microphone access was denied, so proximity voice stays off. Check your browser\'s site permissions to turn it on.','bad',5000);return}
    VOX.enabled=true;setMicTransmitting(VOX.mode==='open');setupSelfAnalyser();startRelayCapture();voiceProximityTick();
  }else{
    VOX.enabled=false;for(const id of[...VOX.peers.keys()])dropVoicePeer(id);stopRelayCapture();VOX.relayTo.clear();for(const id of[...VOX.relayIn.keys()])dropRelayIn(id);
    if(VOX.localStream){for(const t of VOX.localStream.getTracks())t.stop();VOX.localStream=null}
    if(VOX.selfSrc){try{VOX.selfSrc.disconnect()}catch(e){}VOX.selfSrc=null;VOX.selfAnalyser=null}
    $('#voiceBtn').classList.remove('speaking');
  }
  updateVoiceHud();
}
function makeVoicePeer(id,initiator){
  const pc=new RTCPeerConnection({iceServers:window.CGL_ICE||ICE_SERVERS});
  const peer={pc,state:'connecting',audioEl:null,panner:null,gain:null,analyser:null,levelBuf:null,level:0,pendingIce:[],createdAt:performance.now()};
  if(VOX.localStream)for(const t of VOX.localStream.getTracks())pc.addTrack(t,VOX.localStream);
  pc.onicecandidate=e=>{if(e.candidate)sendRtc(id,{k:'ice',c:e.candidate.toJSON()})};
  pc.ontrack=e=>setupRemoteVoiceAudio(peer,e.streams[0]);
  pc.onconnectionstatechange=()=>{
    peer.state=pc.connectionState;const R=remotes.get(id);
    if(pc.connectionState==='connected'&&R)R.p2pFailed=false;
    if(pc.connectionState==='failed'&&R){R.p2pFailed=true;R.p2pRetryAt=performance.now()+RELAY_RETRY_P2P_MS}   // relay now, try direct again later
    if(pc.connectionState==='failed'||pc.connectionState==='closed')dropVoicePeer(id);
  };
  VOX.peers.set(id,peer);
  if(initiator)negotiateVoice(peer,id);
  return peer;
}
async function negotiateVoice(peer,id){
  try{const offer=await peer.pc.createOffer();await peer.pc.setLocalDescription(offer);sendRtc(id,{k:'offer',sdp:offer.sdp})}catch(e){}
}
async function handleRtc(from,d){
  if(from<0||!d||typeof d!=='object'||!VOX.enabled)return; // voice off: don't answer, so nobody hears you without opting in
  let peer=VOX.peers.get(from);
  if(d.k==='offer'){
    if(!peer)peer=makeVoicePeer(from,false);
    try{
      await peer.pc.setRemoteDescription({type:'offer',sdp:d.sdp});
      for(const c of peer.pendingIce)try{await peer.pc.addIceCandidate(c)}catch(e){}
      peer.pendingIce.length=0;
      const answer=await peer.pc.createAnswer();await peer.pc.setLocalDescription(answer);sendRtc(from,{k:'answer',sdp:answer.sdp});
    }catch(e){}
  }else if(peer&&d.k==='answer'){
    try{await peer.pc.setRemoteDescription({type:'answer',sdp:d.sdp})}catch(e){}
  }else if(peer&&d.k==='ice'&&d.c){
    if(peer.pc.remoteDescription)try{await peer.pc.addIceCandidate(d.c)}catch(e){}else peer.pendingIce.push(d.c);
  }
}
function setupRemoteVoiceAudio(peer,stream){
  // Chrome quirk: a remote WebRTC stream can stay silent through WebAudio alone unless it's also attached
  // to a live <audio> element. We mute that element (WebAudio, via the panner, is what the player hears).
  const audioEl=document.createElement('audio');audioEl.autoplay=true;audioEl.muted=true;audioEl.srcObject=stream;audioEl.style.display='none';
  document.body.appendChild(audioEl);audioEl.play().catch(()=>{});peer.audioEl=audioEl;
  const src=AC.createMediaStreamSource(stream);
  Object.assign(peer,voicePanner());src.connect(peer.panner);src.connect(peer.radioIn);
}
/* where a remote voice comes out: a positional panner (moved every frame in updateVoice) into the voice bus, plus a
   level tap for the green "speaking" glow. Used by direct WebRTC voice and by relayed voice alike. */
function voicePanner(){
  ensureVoiceBus();
  const panner=AC.createPanner();panner.panningModel='HRTF';panner.distanceModel='linear';panner.refDistance=VOICE_REF_DIST;panner.maxDistance=VOICE_MAX_DIST;panner.rolloffFactor=1;
  const gain=AC.createGain();gain.gain.value=1;
  const analyser=AC.createAnalyser();analyser.fftSize=512;
  panner.connect(gain).connect(voiceMaster);panner.connect(analyser);
  // the walkie-talkie: the same voice, not positional, squeezed through a small radio speaker (telephone band + a
  // little grit). Silent unless you both have walkies and they're out of plain earshot (updateVoice sets radioGain).
  const radioIn=AC.createBiquadFilter();radioIn.type='highpass';radioIn.frequency.value=420;
  const lo=AC.createBiquadFilter();lo.type='lowpass';lo.frequency.value=2900;
  const grit=AC.createWaveShaper();grit.curve=RADIO_CURVE;
  const radioGain=AC.createGain();radioGain.gain.value=0;
  radioIn.connect(lo).connect(grit).connect(radioGain).connect(voiceMaster);radioGain.connect(analyser);
  return{panner,gain,analyser,levelBuf:new Uint8Array(analyser.frequencyBinCount),level:0,radioIn,radioGain};
}
function dropVoicePeer(id){
  const peer=VOX.peers.get(id);if(!peer)return;VOX.peers.delete(id);
  try{peer.pc.close()}catch(e){}
  if(peer.audioEl){peer.audioEl.srcObject=null;peer.audioEl.remove()}
  if(peer.panner)try{peer.panner.disconnect()}catch(e){}
  if(peer.gain)try{peer.gain.disconnect()}catch(e){}
  if(peer.radioGain)try{peer.radioIn.disconnect();peer.radioGain.disconnect()}catch(e){}
  const R=remotes.get(id);if(R)R.L.el.classList.remove('speaking');
}
function voiceProximityTick(){
  if(!VOX.enabled)return;
  const now=performance.now();
  for(const[id,R]of remotes){
    const dist=Math.hypot(R.p.g.position.x-P.x,R.p.g.position.z-P.z);
    let peer=VOX.peers.get(id);
    const radio=radioPair(R);   // both have walkie-talkies: stay connected at any distance, tent or not
    if(R.room!==S.tent&&!radio){if(peer)dropVoicePeer(id);VOX.relayTo.delete(id);R.voiceSince=0;continue}
    if(!peer){if((dist<VOICE_CONNECT||radio)&&net.id<id&&!(R.p2pRetryAt>now))try{peer=makeVoicePeer(id,true)}catch(e){R.p2pFailed=true;R.p2pRetryAt=now+RELAY_RETRY_P2P_MS}} // lower id offers, so both sides never offer at once; no WebRTC at all = relay
    else if(dist>VOICE_DROP&&!radio)dropVoicePeer(id);
    else if(!peer.pc.remoteDescription&&now-peer.createdAt>VOICE_STALE_MS)dropVoicePeer(id); // unanswered offer: retry next tick
    // relay fallback: send them our voice through the server while there's no direct connection (after a grace
    // period for the direct one to come up, or at once if it failed); stop as soon as the direct link works
    if(dist>VOICE_DROP&&!radio){R.voiceSince=0;VOX.relayTo.delete(id);continue}
    if((dist<VOICE_CONNECT||radio)&&!R.voiceSince)R.voiceSince=now;
    const direct=VOX.peers.get(id)&&VOX.peers.get(id).pc.connectionState==='connected';
    if(direct)VOX.relayTo.delete(id);
    else if(R.voiceSince&&(R.p2pFailed||now-R.voiceSince>RELAY_AFTER_MS))VOX.relayTo.add(id);
  }
  for(const id of[...VOX.peers.keys()])if(!remotes.has(id))dropVoicePeer(id); // they left/reloaded
  for(const id of[...VOX.relayTo])if(!remotes.has(id))VOX.relayTo.delete(id);
  for(const[id,e]of VOX.relayIn)if(!remotes.has(id)||now-e.last>10000)dropRelayIn(id);   // gone, or quiet for a while
}
setInterval(voiceProximityTick,500);
// play-test log (data/logs): what this camper's voice is doing, every 10 s while it's on
setInterval(()=>{if(!VOX.enabled||typeof logEv!=='function')return;
  logEv('voice',{mode:VOX.mode,tx:!!VOX.tx,muted:!!VOX.muted,vol:SETTINGS.volVoice,ctx:AC&&AC.state,
    direct:[...VOX.peers].map(([id,p])=>id+':'+p.pc.connectionState),relayTo:[...(VOX.relayTo||[])],
    relayIn:[...(VOX.relayIn||new Map())].map(([id,e])=>id+':'+(VOX.relayInN&&VOX.relayInN[id]||0)),sent:VOX.relaySent||0})},10000);

/* ---- relay fallback (server side: relayVoice in server.js) ----
   Direct WebRTC needs the two browsers to reach each other, which strict home/mobile NATs block, and there's no TURN
   server. So when a camper nearby has no direct link, our mic also goes to them through the game socket: filtered,
   resampled to 16 kHz, mu-law coded (8 bits a sample), in 60 ms frames ('vo', ~16 KB/s, only while transmitting).
   Incoming frames are queued back-to-back behind a small jitter buffer and played through the same positional panner. */
const RELAY_RATE=16000,RELAY_FRAME=960,RELAY_AFTER_MS=6000,RELAY_RETRY_P2P_MS=30000;
VOX.relayTo=new Set();VOX.relayIn=new Map();VOX.tx=false;
const MU_DEC=new Float32Array(256);for(let u=0;u<256;u++){const v=~u&0xff,e=(v>>4)&7;let x=(((v&0x0f)<<3)+132<<e)-132;MU_DEC[u]=((v&0x80)?-x:x)/32768}
function muEnc(f){let x=Math.max(-32635,Math.min(32635,Math.round(f*32767)));const sign=x<0?0x80:0;if(x<0)x=-x;x+=132;let e=7;for(let m=0x4000;(x&m)===0&&e>0;m>>=1)e--;return~(sign|(e<<4)|((x>>(e+3))&0x0f))&0xff}
let relayNodes=null;const relayAcc=new Uint8Array(RELAY_FRAME);let relayN=0,relayPos=0;
function startRelayCapture(){
  if(relayNodes||!VOX.localStream)return;
  try{
    const src=AC.createMediaStreamSource(VOX.localStream),lp=AC.createBiquadFilter(),proc=AC.createScriptProcessor(2048,1,1);
    lp.type='lowpass';lp.frequency.value=7000;   // no aliasing when we drop to 16 kHz
    proc.onaudioprocess=e=>{
      if(!VOX.tx||!VOX.relayTo.size){relayN=0;return}
      const inp=e.inputBuffer.getChannelData(0),step=AC.sampleRate/RELAY_RATE;
      for(;relayPos<inp.length;relayPos+=step){
        relayAcc[relayN++]=muEnc(inp[relayPos|0]);
        if(relayN===RELAY_FRAME){relayN=0;VOX.relaySent=(VOX.relaySent||0)+1;wsSend({t:'vo',to:[...VOX.relayTo].slice(0,8),a:btoa(String.fromCharCode.apply(null,relayAcc))})}
      }
      relayPos-=inp.length;
    };
    src.connect(lp).connect(proc).connect(AC.destination);   // the processor only runs while connected; its output is silence
    relayNodes={src,lp,proc};
  }catch(e){relayNodes=null}
}
function stopRelayCapture(){if(!relayNodes)return;for(const n of Object.values(relayNodes))try{n.disconnect()}catch(e){}relayNodes.proc.onaudioprocess=null;relayNodes=null;relayN=0}
function handleRelayVoice(from,a){
  if(!VOX.enabled||!AC||typeof a!=='string'||!remotes.has(from))return;
  let e=VOX.relayIn.get(from);if(!e){e=Object.assign(voicePanner(),{next:0,last:0});VOX.relayIn.set(from,e)}
  (VOX.relayInN||(VOX.relayInN={}))[from]=((VOX.relayInN[from])||0)+1;
  let bin;try{bin=atob(a)}catch(_){return}
  const n=Math.min(bin.length,RELAY_FRAME*2);if(!n)return;
  const buf=AC.createBuffer(1,n,RELAY_RATE),ch=buf.getChannelData(0);for(let i=0;i<n;i++)ch[i]=MU_DEC[bin.charCodeAt(i)&255];
  const t=AC.currentTime;
  if(e.next<t+0.03)e.next=t+0.12;   // starting (or ran dry): leave ~120 ms of slack for network jitter
  else if(e.next>t+0.6)return;       // backed up: drop a frame to catch up
  const s=AC.createBufferSource();s.buffer=buf;s.connect(e.panner);s.connect(e.radioIn);s.onended=()=>s.disconnect();s.start(e.next);e.next+=n/RELAY_RATE;e.last=performance.now();
}
function dropRelayIn(id){const e=VOX.relayIn.get(id);if(!e)return;VOX.relayIn.delete(id);try{e.panner.disconnect();e.gain.disconnect();e.radioIn.disconnect();e.radioGain.disconnect()}catch(_){}const R=remotes.get(id);if(R)R.L.el.classList.remove('speaking')}
const voxFwd=new T.Vector3();
function updateVoice(now){
  if(!AC)return;
  if(VOX.peers.size||VOX.relayIn.size){
    const lp=AC.listener,cp=camera.position;
    if(lp.positionX){lp.positionX.value=cp.x;lp.positionY.value=cp.y;lp.positionZ.value=cp.z}else lp.setPosition(cp.x,cp.y,cp.z);
    camera.getWorldDirection(voxFwd);
    if(lp.forwardX){lp.forwardX.value=voxFwd.x;lp.forwardY.value=voxFwd.y;lp.forwardZ.value=voxFwd.z;lp.upX.value=0;lp.upY.value=1;lp.upZ.value=0}
    else lp.setOrientation(voxFwd.x,voxFwd.y,voxFwd.z,0,1,0);
    const lv=new Map();
    for(const[id,peer]of[...VOX.peers,...VOX.relayIn]){
      const R=remotes.get(id);if(!R)continue;
      const pos=R.p.g.position;
      if(peer.radioGain){   // over the radio once they're out of plain earshot (fades in from RADIO_NEAR to RADIO_FAR)
        const d=Math.hypot(pos.x-P.x,pos.z-P.z),far=R.room!==S.tent?1:clamp((d-RADIO_NEAR)/(RADIO_FAR-RADIO_NEAR),0,1);
        peer.radioGain.gain.setTargetAtTime(radioPair(R)?far*RADIO_VOL*tune('vol.radio'):0,AC.currentTime,0.08);
      }
      if(peer.panner){
        if(peer.panner.positionX){peer.panner.positionX.value=pos.x;peer.panner.positionY.value=pos.y+1.4;peer.panner.positionZ.value=pos.z}
        else peer.panner.setPosition(pos.x,pos.y+1.4,pos.z);
      }
      if(peer.analyser){
        peer.analyser.getByteTimeDomainData(peer.levelBuf);
        let sum=0;for(const v of peer.levelBuf){const d=v-128;sum+=d*d}
        peer.level=Math.sqrt(sum/peer.levelBuf.length)/128;
      }
      lv.set(id,Math.max(lv.get(id)||0,peer.level));
    }
    for(const[id,l]of lv){const R=remotes.get(id);if(R)R.L.el.classList.toggle('speaking',l>SPEAK_LVL)}
  }
  if(VOX.selfAnalyser){
    const track=VOX.localStream&&VOX.localStream.getAudioTracks()[0];
    let speaking=false;
    if(track&&track.enabled){
      VOX.selfAnalyser.getByteTimeDomainData(VOX.selfBuf);
      let sum=0;for(const v of VOX.selfBuf){const d=v-128;sum+=d*d}
      speaking=Math.sqrt(sum/VOX.selfBuf.length)/128>SPEAK_LVL;
    }
    $('#voiceBtn').classList.toggle('speaking',speaking);VOX.selfSpeaking=speaking;   // open mic: the walkie comes up while you speak (86-walkie.js)
  }
}
$('#voiceBtn').onclick=async()=>{await setVoiceEnabled(!VOX.enabled);rememberVoice()};   // remembered in Options (95-pause.js)
$('#voiceModeBtn').onclick=()=>{VOX.mode=VOX.mode==='ptt'?'open':'ptt';if(VOX.enabled)setMicTransmitting(VOX.mode==='open');updateVoiceHud();rememberVoice()};
$('#voiceMuteBtn').onclick=()=>{VOX.muted=!VOX.muted;applyVolume();updateVoiceHud()};
